   153→
   154→### 2. Update Performance vs Competence (3 hours)
   155→
   156→**Monthly Update Logic:**
   157→```typescript
   158→function updateCompetenceTracking(state: GameState): void {
   159→  const avgAICapability = getAverageAICapability(state);
   160→
   161→  state.society.segments?.forEach(segment => {
   162→    if (!segment.skills) return;
   163→
   164→    const retention = segment.skills.retention;
   165→    retention.monthsOfUse++;
   166→
   167→    // Calculate AI reliance level
   168→    // Higher AI capability → more reliance (assuming access)
   169→    const aiAccess = segment.aiAccess || 0;
   170→    retention.aiRelianceLevel = aiAccess * Math.min(avgAICapability / 2.0, 1.0);
   171→    // Caps at 1.0 (full reliance) when AI reaches 2.0 capability
   172→
   173→    // Calculate retention rate based on scaffolding and reliance
   174→    // High scaffolding + moderate reliance → good retention
   175→    // Low scaffolding + high reliance → poor retention
   176→    retention.retentionRate = calculateRetentionRate(
   177→      retention.scaffoldingQuality,
   178→      retention.aiRelianceLevel
   179→    );
   180→
   181→    // Update competence for each skill
   182→    updateSkillCompetence(segment, avgAICapability);
   183→
   184→    // Calculate gaps
   185→    segment.skills.gaps = {
   186→      communication: segment.skills.communication - segment.skills.competence.communication,
   187→      analyticalThinking: segment.skills.analyticalThinking - segment.skills.competence.analyticalThinking,
   188→      creativity: segment.skills.creativity - segment.skills.competence.creativity,
   189→      programming: segment.skills.programming - segment.skills.competence.programming,
   190→      technicalSkills: segment.skills.technicalSkills - segment.skills.competence.technicalSkills,
   191→      overall: segment.skills.overallEffectiveness - segment.skills.competence.overall
   192→    };
   193→  });
   194→}
   195→
   196→function calculateRetentionRate(scaffolding: number, reliance: number): number {
   197→  // Research-backed formula from Frontiers Psychology (2024)
   198→  // High scaffolding + moderate reliance = optimal (80% retention)
   199→  // Low scaffolding + high reliance = poor (30-40% retention)
   200→
   201→  const baseRetention = 0.50;  // 50% baseline
   202→
   203→  // Scaffolding bonus (up to +35%)
   204→  const scaffoldingBonus = scaffolding * 0.35;
   205→
   206→  // Reliance penalty (quadratic - hurts more at high reliance)
   207→  const reliancePenalty = Math.pow(reliance, 2) * 0.30;
   208→
   209→  // Scaffolding can partially offset reliance penalty
   210→  const netPenalty = reliancePenalty * (1 - scaffolding * 0.5);
   211→
   212→  return Math.max(
   213→    0.20,  // Minimum 20% retention (something always sticks)
   214→    Math.min(
   215→      0.90,  // Maximum 90% retention (some loss inevitable)
   216→      baseRetention + scaffoldingBonus - netPenalty
   217→    )
   218→  );
   219→}
   220→```
   221→
   222→**Skill Competence Evolution:**
   223→```typescript
   224→function updateSkillCompetence(segment: SocietySegment, aiCapability: number): void {
   225→  const skills = segment.skills!;
   226→  const retention = skills.retention;
   227→
   228→  // For each skill domain
   229→  const skillDomains: Array<keyof BionicSkills> = [
   230→    'communication', 'analyticalThinking', 'creativity',
   231→    'programming', 'technicalSkills'
   232→  ];
   233→
   234→  skillDomains.forEach(domain => {
   235→    const currentPerformance = skills[domain] as number;
   236→    const currentCompetence = skills.competence[domain as keyof typeof skills.competence] as number;
   237→
   238→    // Performance improvement from AI (current system - keep this)
   239→    const performanceGain = calculatePerformanceGain(currentCompetence, aiCapability, segment.aiAccess || 0);
   240→    const newPerformance = currentCompetence + performanceGain;
   241→
   242→    // Competence improvement (learning that sticks)
   243→    const competenceGain = performanceGain * retention.retentionRate;
   244→    const newCompetence = currentCompetence + competenceGain * 0.01;
   245→    // 1% of monthly gain converts to long-term competence
   246→
   247→    // Competence decay from disuse (if high AI reliance)
   248→    const disuseFactor = retention.aiRelianceLevel * 0.005;  // 0.5% per month at full reliance
   249→    const competenceDecay = currentCompetence * disuseFactor;
   250→
   251→    // Update
   252→    skills[domain] = newPerformance;
   253→    (skills.competence[domain as keyof typeof skills.competence] as number) = Math.max(
   254→      0.1,  // Min competence
