   133→ *   baselineMortality: 0.001,
   134→ *   peakMortality: 0.0025,
   135→ *   affectedFraction: 1.0,
   136→ *   economicImpact: 0.4,
   137→ *   techResilience: true,
   138→ *   vaccineTimeline: 12
   139→ * });
   140→ * ```
   141→ */
   142→export function triggerPandemic(
   143→  state: GameState,
   144→  params: PandemicEventParams
   145→): void {
   146→  // Initialize triggered events state if needed
   147→  if (!state.triggeredEvents) {
   148→    state.triggeredEvents = initializeTriggeredEvents();
   149→  }
   150→
   151→  const event: PandemicEvent = {
   152→    id: `pandemic_${Date.now()}`,
   153→    type: 'pandemic',
   154→    startMonth: params.startMonth,
   155→    duration: params.duration,
   156→    active: false, // Will activate when currentMonth reaches startMonth
   157→    params,
   158→    phaseData: {
   159→      currentPhase: 'outbreak',
   160→      monthsSinceStart: 0,
   161→      cumulativeDeaths: 0,
   162→      economicImpactApplied: false
   163→    }
   164→  };
   165→
   166→  state.triggeredEvents.activeEvents.push(event);
   167→
   168→  console.log(`\n📋 PANDEMIC EVENT SCHEDULED (Month ${params.startMonth})`);
   169→  console.log(`   Duration: ${params.duration} months`);
   170→  console.log(`   Mortality: ${(params.baselineMortality * 100).toFixed(2)}% baseline, ${(params.peakMortality * 100).toFixed(2)}% peak`);
   171→  console.log(`   Affected: ${(params.affectedFraction * 100).toFixed(0)}% of population`);
   172→  console.log(`   Economic impact: ${(params.economicImpact * 100).toFixed(0)}%`);
   173→  if (params.vaccineTimeline) {
   174→    console.log(`   Vaccine timeline: ${params.vaccineTimeline} months`);
   175→  }
   176→  console.log('');
   177→}
   178→
   179→/**
   180→ * Process active pandemic event
   181→ *
   182→ * Handles phase transitions and applies mortality + economic impacts.
   183→ */
   184→function processPandemicEvent(
   185→  state: GameState,
   186→  event: PandemicEvent
   187→): void {
   188→  const { params, phaseData } = event;
   189→  phaseData.monthsSinceStart = state.currentMonth - event.startMonth;
   190→  const progress = phaseData.monthsSinceStart / params.duration;
   191→
   192→  // === PHASE TRANSITIONS ===
   193→  if (progress < 0.2) {
   194→    phaseData.currentPhase = 'outbreak';
   195→  } else if (progress < 0.4) {
   196→    phaseData.currentPhase = 'peak';
   197→  } else if (progress < 0.8) {
   198→    phaseData.currentPhase = 'decline';
   199→  } else {
   200→    phaseData.currentPhase = 'recovery';
   201→  }
   202→
   203→  // === MORTALITY CALCULATION ===
   204→  // Mortality follows a curve: outbreak → peak → decline → recovery
   205→  let currentMortality = params.baselineMortality;
   206→
   207→  switch (phaseData.currentPhase) {
   208→    case 'outbreak':
   209→      // Ramping up from baseline to peak
   210→      const outbreakProgress = progress / 0.2; // 0-1 within outbreak phase
   211→      currentMortality = params.baselineMortality +
   212→        (params.peakMortality - params.baselineMortality) * outbreakProgress;
   213→      break;
   214→
   215→    case 'peak':
   216→      // Maximum mortality
   217→      currentMortality = params.peakMortality;
   218→      break;
   219→
   220→    case 'decline':
   221→      // Declining from peak to baseline
   222→      const declineProgress = (progress - 0.4) / 0.4; // 0-1 within decline phase
   223→      currentMortality = params.peakMortality -
   224→        (params.peakMortality - params.baselineMortality) * declineProgress;
   225→      break;
   226→
   227→    case 'recovery':
   228→      // Vaccine effect (if applicable)
   229→      if (params.vaccineTimeline && phaseData.monthsSinceStart >= params.vaccineTimeline) {
   230→        const vaccineProgress = (phaseData.monthsSinceStart - params.vaccineTimeline) /
   231→                                (params.duration - params.vaccineTimeline);
   232→        currentMortality = params.baselineMortality * (1 - vaccineProgress * 0.9); // 90% reduction
   233→      } else {
   234→        currentMortality = params.baselineMortality;
   235→      }
   236→      break;
   237→  }
   238→
   239→  // Apply mortality
   240→  const { addAcuteCrisisDeaths } = require('./populationDynamics');
   241→  const deathsThisMonth = state.humanPopulationSystem.population *
   242→                          currentMortality *
   243→                          params.affectedFraction;
   244→
   245→  addAcuteCrisisDeaths(
   246→    state,
   247→    currentMortality,
   248→    `Pandemic - ${phaseData.currentPhase} phase`,
   249→    params.affectedFraction,
   250→    'disease'
   251→  );
   252→
   253→  phaseData.cumulativeDeaths += deathsThisMonth;
   254→
   255→  // === ECONOMIC IMPACTS (applied once) ===
   256→  if (!phaseData.economicImpactApplied && phaseData.currentPhase === 'peak') {
   257→    applyPandemicEconomicImpact(state, params);
   258→    phaseData.economicImpactApplied = true;
   259→  }
   260→
   261→  // === TECH SECTOR BOOST (modern pandemics only) ===
   262→  if (params.techResilience && phaseData.currentPhase === 'peak') {
   263→    // Tech companies thrive during pandemic (remote work, cloud, e-commerce)
   264→    const techOrgs = state.organizations.filter(org =>
   265→      org.name.toLowerCase().includes('tech') ||
   266→      org.name.toLowerCase().includes('google') ||
   267→      org.name.toLowerCase().includes('amazon') ||
   268→      org.name.toLowerCase().includes('microsoft')
   269→    );
   270→
   271→    techOrgs.forEach(org => {
   272→      org.monthlyRevenue *= 1.02; // +2% per month during peak (compounds to +20-40% over year)
   273→      org.capital *= 1.01; // Profit accumulation
   274→    });
   275→  }
   276→
   277→  // === LOGGING ===
   278→  if (phaseData.monthsSinceStart % 6 === 0) { // Log every 6 months
   279→    console.log(`\n🦠 PANDEMIC (Month ${state.currentMonth}): ${phaseData.currentPhase.toUpperCase()} PHASE`);
   280→    console.log(`   Progress: ${(progress * 100).toFixed(1)}% (${phaseData.monthsSinceStart}/${params.duration} months)`);
   281→    console.log(`   Current mortality: ${(currentMortality * 100).toFixed(3)}%/month`);
   282→    console.log(`   Cumulative deaths: ${(phaseData.cumulativeDeaths / 1_000_000).toFixed(2)}M`);
   283→    console.log(`   Population: ${(state.humanPopulationSystem.population / 1_000_000_000).toFixed(2)}B`);
   284→    console.log('');
   285→  }
   286→
   287→  // === COMPLETION ===
   288→  if (progress >= 1.0) {
   289→    event.active = false;
   290→    console.log(`\n✅ PANDEMIC COMPLETED (Month ${state.currentMonth})`);
   291→    console.log(`   Total deaths: ${(phaseData.cumulativeDeaths / 1_000_000).toFixed(2)}M`);
   292→    console.log(`   Mortality rate: ${(phaseData.cumulativeDeaths / (state.humanPopulationSystem.population + phaseData.cumulativeDeaths) * 100).toFixed(3)}%`);
   293→    console.log('');
   294→  }
   295→}
   296→
   297→/**
   298→ * Apply pandemic economic impacts
   299→ */
   300→function applyPandemicEconomicImpact(
   301→  state: GameState,
   302→  params: PandemicEventParams
   303→): void {
   304→  // Unemployment spike (temporary)
   305→  const unemploymentIncrease = 0.05 * params.economicImpact; // Up to 5% increase
   306→  state.society.unemploymentLevel = Math.min(0.9,
   307→    state.society.unemploymentLevel + unemploymentIncrease
   308→  );
   309→
   310→  // Social stability hit
   311→  state.globalMetrics.socialStability = Math.max(0.2,
   312→    state.globalMetrics.socialStability - 0.1 * params.economicImpact
   313→  );
   314→
   315→  // QoL impacts (temporary)
   316→  state.qualityOfLifeSystems.materialAbundance *= (1 - 0.1 * params.economicImpact);
   317→  state.qualityOfLifeSystems.socialConnection *= (1 - 0.2 * params.economicImpact);
   318→  state.qualityOfLifeSystems.mentalHealth *= (1 - 0.15 * params.economicImpact);
   319→
   320→  console.log(`\n💰 PANDEMIC ECONOMIC IMPACT APPLIED`);
   321→  console.log(`   Unemployment: +${(unemploymentIncrease * 100).toFixed(1)}%`);
   322→  console.log(`   Social stability: -${(0.1 * params.economicImpact).toFixed(2)}`);
   323→  console.log('');
   324→}
   325→
   326→// ============================================================================
   327→// ECONOMIC CRISIS EVENTS
   328→// ============================================================================
   329→
   330→/**
   331→ * Trigger an economic crisis event
   332→ *
   333→ * @param state - Game state
   334→ * @param params - Economic crisis parameters
   335→ *
   336→ * Example usage (2008 Financial Crisis):
   337→ * ```
   338→ * triggerEconomicCrisis(state, {
   339→ *   startMonth: 9,
   340→ *   duration: 48,
   341→ *   severity: 0.7,
   342→ *   organizationalImpact: {
   343→ *     tech: 0.05,
   344→ *     finance: 0.30,
   345→ *     general: 0.15
   346→ *   },
   347→ *   unemploymentSpike: 0.05,
   348→ *   wealthInequalityIncrease: 0.04,
   349→ *   governmentResponse: true
   350→ * });
   351→ * ```
   352→ */
   353→export function triggerEconomicCrisis(
   354→  state: GameState,
   355→  params: EconomicCrisisParams
   356→): void {
   357→  // Initialize triggered events state if needed
   358→  if (!state.triggeredEvents) {
   359→    state.triggeredEvents = initializeTriggeredEvents();
   360→  }
   361→
   362→  const event: EconomicCrisisEvent = {
   363→    id: `economic_crisis_${Date.now()}`,
   364→    type: 'economic_crisis',
   365→    startMonth: params.startMonth,
   366→    duration: params.duration,
   367→    active: false,
   368→    params,
   369→    phaseData: {
   370→      currentPhase: 'shock',
   371→      monthsSinceStart: 0,
   372→      bankruptcyWaveComplete: false,
   373→      peakUnemployment: 0
   374→    }
   375→  };
   376→
   377→  state.triggeredEvents.activeEvents.push(event);
   378→
   379→  console.log(`\n📉 ECONOMIC CRISIS EVENT SCHEDULED (Month ${params.startMonth})`);
   380→  console.log(`   Duration: ${params.duration} months`);
   381→  console.log(`   Severity: ${(params.severity * 100).toFixed(0)}%`);
   382→  console.log(`   Bankruptcy rates: Tech ${(params.organizationalImpact.tech * 100).toFixed(0)}%, Finance ${(params.organizationalImpact.finance * 100).toFixed(0)}%, General ${(params.organizationalImpact.general * 100).toFixed(0)}%`);
   383→  console.log(`   Unemployment spike: +${(params.unemploymentSpike * 100).toFixed(1)}%`);
   384→  console.log(`   Government response: ${params.governmentResponse ? 'YES (bailouts)' : 'NO'}`);
   385→  console.log('');
   386→}
   387→
   388→/**
   389→ * Process active economic crisis event
   390→ *
   391→ * Handles phase transitions and applies organizational/economic impacts.
   392→ */
   393→function processEconomicCrisisEvent(
   394→  state: GameState,
   395→  event: EconomicCrisisEvent
   396→): void {
   397→  const { params, phaseData } = event;
   398→  phaseData.monthsSinceStart = state.currentMonth - event.startMonth;
   399→  const progress = phaseData.monthsSinceStart / params.duration;
   400→
   401→  // === PHASE TRANSITIONS ===
   402→  if (progress < 0.1) {
   403→    phaseData.currentPhase = 'shock';
   404→  } else if (progress < 0.4) {
   405→    phaseData.currentPhase = 'crisis';
   406→  } else if (progress < 0.7) {
   407→    phaseData.currentPhase = 'stabilization';
   408→  } else {
   409→    phaseData.currentPhase = 'recovery';
   410→  }
   411→
   412→  // === BANKRUPTCY WAVE (applied once) ===
   413→  if (!phaseData.bankruptcyWaveComplete && phaseData.currentPhase === 'crisis') {
   414→    applyEconomicCrisisBankruptcies(state, params);
   415→    phaseData.bankruptcyWaveComplete = true;
   416→  }
   417→
   418→  // === UNEMPLOYMENT DYNAMICS ===
   419→  const unemploymentCurve = calculateUnemploymentCurve(progress);
   420→  const currentUnemployment = state.society.unemploymentLevel +
   421→                              (params.unemploymentSpike * unemploymentCurve);
   422→  state.society.unemploymentLevel = Math.min(0.9, currentUnemployment);
   423→  phaseData.peakUnemployment = Math.max(phaseData.peakUnemployment, currentUnemployment);
   424→
   425→  // === WEALTH INEQUALITY ===
   426→  // Top 1% recovers faster, bottom 50% slower
   427→  if (phaseData.currentPhase === 'crisis' || phaseData.currentPhase === 'stabilization') {
   428→    state.globalMetrics.wealthDistribution = Math.max(0.3,
   429→      state.globalMetrics.wealthDistribution - params.wealthInequalityIncrease * 0.01
   430→    );
   431→  }
   432→
   433→  // === SOCIAL STABILITY ===
   434→  const stabilityImpact = params.severity * (1 - progress) * 0.005;
   435→  state.globalMetrics.socialStability = Math.max(0.3,
   436→    state.globalMetrics.socialStability - stabilityImpact
   437→  );
   438→
   439→  // === GOVERNMENT RESPONSE ===
   440→  if (params.governmentResponse && phaseData.currentPhase === 'crisis') {
   441→    // Bailouts, stimulus, etc.
   442→    state.government.alignmentResearchInvestment = Math.min(10,
   443→      state.government.alignmentResearchInvestment + 1
   444→    );
   445→
   446→    // Prevent additional org bankruptcies (bailout effect)
   447→    state.organizations.forEach(org => {
   448→      if (!org.bankrupt && org.capital < 0) {
   449→        org.capital *= 0.8; // Government support reduces losses
   450→      }
   451→    });
   452→  }
   453→
   454→  // === LOGGING ===
   455→  if (phaseData.monthsSinceStart % 12 === 0 || phaseData.monthsSinceStart === 1) {
   456→    console.log(`\n📉 ECONOMIC CRISIS (Month ${state.currentMonth}): ${phaseData.currentPhase.toUpperCase()} PHASE`);
   457→    console.log(`   Progress: ${(progress * 100).toFixed(1)}% (${phaseData.monthsSinceStart}/${params.duration} months)`);
   458→    console.log(`   Unemployment: ${(currentUnemployment * 100).toFixed(1)}%`);
   459→    console.log(`   Wealth distribution: ${state.globalMetrics.wealthDistribution.toFixed(3)}`);
   460→    console.log(`   Organizations: ${state.organizations.filter(o => !o.bankrupt).length}/${state.organizations.length} active`);
   461→    console.log('');
   462→  }
   463→
   464→  // === COMPLETION ===
   465→  if (progress >= 1.0) {
   466→    event.active = false;
   467→    console.log(`\n✅ ECONOMIC CRISIS RESOLVED (Month ${state.currentMonth})`);
   468→    console.log(`   Peak unemployment: ${(phaseData.peakUnemployment * 100).toFixed(1)}%`);
   469→    console.log(`   Organizations survived: ${state.organizations.filter(o => !o.bankrupt).length}/${state.organizations.length}`);
   470→    console.log('');
   471→  }
   472→}
   473→
   474→/**
   475→ * Calculate unemployment curve during economic crisis
   476→ *
   477→ * Unemployment spikes quickly, plateaus, then gradually recovers.
   478→ */
   479→function calculateUnemploymentCurve(progress: number): number {
   480→  if (progress < 0.2) {
   481→    // Rapid spike (0-20% of crisis)
   482→    return progress / 0.2; // 0 → 1
   483→  } else if (progress < 0.6) {
   484→    // Plateau (20-60% of crisis)
   485→    return 1.0;
   486→  } else {
   487→    // Gradual recovery (60-100% of crisis)
   488→    return 1 - ((progress - 0.6) / 0.4); // 1 → 0
   489→  }
   490→}
   491→
   492→/**
   493→ * Apply sector-specific organizational bankruptcies
   494→ *
   495→ * CRITICAL FIX: Current simulation shows 100% bankruptcy.
   496→ * This function implements realistic sector-based bankruptcy rates.
   497→ */
   498→function applyEconomicCrisisBankruptcies(
   499→  state: GameState,
   500→  params: EconomicCrisisParams
   501→): void {
   502→  let techBankrupt = 0;
   503→  let financeBankrupt = 0;
   504→  let generalBankrupt = 0;
   505→
   506→  state.organizations.forEach(org => {
   507→    if (org.bankrupt) return; // Already bankrupt
   508→
   509→    // Determine sector
   510→    let bankruptcyRate = params.organizationalImpact.general;
   511→    let sector = 'general';
   512→
   513→    const name = org.name.toLowerCase();
   514→    if (name.includes('tech') || name.includes('google') || name.includes('amazon') ||
   515→        name.includes('microsoft') || name.includes('anthropic') || name.includes('openai')) {
   516→      bankruptcyRate = params.organizationalImpact.tech;
   517→      sector = 'tech';
   518→    } else if (name.includes('bank') || name.includes('finance') || name.includes('capital')) {
   519→      bankruptcyRate = params.organizationalImpact.finance;
   520→      sector = 'finance';
   521→    }
   522→
   523→    // Apply bailout effect
   524→    if (params.governmentResponse) {
   525→      bankruptcyRate *= 0.6; // 40% reduction with bailouts
   526→    }
   527→
   528→    // Roll for bankruptcy
   529→    if (Math.random() < bankruptcyRate) {
   530→      org.bankrupt = true;
   531→      org.bankruptcyMonth = state.currentMonth;
   532→      org.bankruptcyReason = `Economic crisis bankruptcy`;
   533→
   534→      if (sector === 'tech') techBankrupt++;
   535→      else if (sector === 'finance') financeBankrupt++;
   536→      else generalBankrupt++;
   537→    } else {
   538→      // Survivors suffer capital loss
   539→      org.capital *= (1 - params.severity * 0.3); // 30% loss at max severity
   540→    }
   541→  });
   542→
   543→  console.log(`\n💸 BANKRUPTCY WAVE (Month ${state.currentMonth})`);
   544→  console.log(`   Tech sector: ${techBankrupt} bankruptcies`);
   545→  console.log(`   Finance sector: ${financeBankrupt} bankruptcies`);
   546→  console.log(`   General sector: ${generalBankrupt} bankruptcies`);
   547→  console.log(`   Total: ${techBankrupt + financeBankrupt + generalBankrupt}/${state.organizations.length}`);
   548→  console.log(`   Survival rate: ${((1 - (techBankrupt + financeBankrupt + generalBankrupt) / state.organizations.length) * 100).toFixed(1)}%`);
   549→  console.log('');
   550→}
   551→
   552→// ============================================================================
   553→// UPDATE LOOP
   554→// ============================================================================
   555→
   556→/**
   557→ * Update all active triggered events
   558→ *
   559→ * Called each month by TriggeredEventsPhase.
   560→ */
   561→export function updateTriggeredEvents(state: GameState): void {
   562→  if (!state.triggeredEvents) {
   563→    return; // No triggered events
   564→  }
   565→
   566→  // Activate events that have reached their start month
   567→  state.triggeredEvents.activeEvents.forEach(event => {
   568→    if (!event.active && state.currentMonth >= event.startMonth) {
   569→      event.active = true;
   570→      console.log(`\n🚨 EVENT TRIGGERED: ${event.type} (Month ${state.currentMonth})`);
   571→    }
   572→  });
   573→
   574→  // Process active events
   575→  state.triggeredEvents.activeEvents.forEach(event => {
   576→    if (!event.active) return;
   577→
   578→    if (event.type === 'pandemic') {
   579→      processPandemicEvent(state, event as PandemicEvent);
   580→    } else if (event.type === 'economic_crisis') {
   581→      processEconomicCrisisEvent(state, event as EconomicCrisisEvent);
   582→    }
   583→  });
   584→
   585→  // Move completed events to history
   586→  const completed = state.triggeredEvents.activeEvents.filter(e => !e.active);
   587→  completed.forEach(event => {
   588→    state.triggeredEvents!.completedEvents.push(event);
   589→  });
   590→  state.triggeredEvents.activeEvents = state.triggeredEvents.activeEvents.filter(e => e.active);
   591→}
   592→

